<?php require_once 'functions.php'; if(is_customer()) redirect('index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$pass=$_POST['password']??''; if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6)$error='Enter valid details. Password must be at least 6 characters.'; else {$s=$conn->prepare('SELECT id FROM customers WHERE email=?');$s->bind_param('s',$email);$s->execute();if($s->get_result()->num_rows)$error='Email already registered.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO customers(name,email,phone,password) VALUES(?,?,?,?)');$s->bind_param('ssss',$name,$email,$phone,$hash);$s->execute();$_SESSION['customer_id']=$s->insert_id;$_SESSION['customer_name']=$name;redirect('index.php');}}} $page_title='Register | '.SHOP_NAME; include 'header.php'; ?><section class="section"><div class="form-card"><h2>Create Account</h2><?php if($error): ?><div class="flash error" style="position:static;margin:12px 0"> <?= e($error) ?> </div><?php endif; ?><form method="post"><div class="form-grid"><div class="form-group"><label>Name</label><input class="form-control" name="name" required></div><div class="form-group"><label>Phone</label><input class="form-control" name="phone" required></div><div class="form-group full"><label>Email</label><input class="form-control" type="email" name="email" required></div><div class="form-group full"><label>Password</label><input class="form-control" type="password" name="password" minlength="6" required></div></div><button class="btn">Register</button> <a href="login.php">Already have an account?</a></form></div></section><?php include 'footer.php'; ?>
